	}
	mc := result.MergedConfig
	if len(mc.PortsAttributes) == 0 && mc.OtherPortsAttributes == nil {
		return nil
	}
	return NewPortAttributeResolver(mc.PortsAttributes, mc.OtherPortsAttributes)
}

